import React, { useEffect, useState } from 'react';
import {
  X,
  Lightbulb,
  BookOpen,
  Calculator,
  PlayCircle,
  CheckCircle2,
  XCircle,
  ChevronLeft,
  ChevronRight,
  Eye,
  EyeOff,
  ListChecks,
  Target, Brain, RotateCcw, ArrowDown, FlaskConical,
} from 'lucide-react';
import type { InteractiveHotspot } from '../types';
import SimulationLab from './simulations/SimulationLab';

// Original, curriculum-aligned practice templates. Each answer is calculated, not generated by an API.
type Drill = { question: string; given: string; formula: string; substitution: string; answer: number; unit: string; trap: string };
type DrillFactory = (n: number) => Drill;
const drills: Record<string, DrillFactory> = {
  weight: n => {const m=2+n;return {question:'احسب وزن جسم على سطح الأرض، بافتراض g = 10 m/s².',given:`m = ${m} kg, g = 10 m/s²`,formula:'W = mg',substitution:`W = ${m} × 10`,answer:m*10,unit:'N',trap:'الكتلة بالكيلوغرام، والوزن قوة تقاس بالنيوتن.'};},
  scalar: n => {const a=2+n,b=3+n;return {question:'متجهان متعامدان. احسب مقدار حاصل ضربهما القياسي.',given:`A = ${a}, B = ${b}, θ = 90°`,formula:'A · B = AB cos θ',substitution:`${a} × ${b} × cos 90°`,answer:0,unit:'',trap:'الضرب القياسي يستخدم جيب التمام؛ cos 90° = 0.'};},
  cross: n => {const a=2+n,b=3+n;return {question:'متجهان متعامدان. احسب مقدار حاصل ضربهما المتجهي.',given:`A = ${a}, B = ${b}, θ = 90°`,formula:'|A × B| = AB sin θ',substitution:`${a} × ${b} × 1`,answer:a*b,unit:'',trap:'الضرب المتجهي يستخدم الجيب، وليس جيب التمام.'};},
  work: n => {const f=10+5*n,d=2+n;return {question:'قوة ثابتة في اتجاه الإزاحة نفسها. احسب الشغل.',given:`F = ${f} N, d = ${d} m, θ = 0°`,formula:'W = Fd cos θ',substitution:`${f} × ${d} × 1`,answer:f*d,unit:'J',trap:'عندما تتفق القوة والإزاحة في الاتجاه تكون cos 0° = 1.'};},
  vector: n => {const k=n+1;return {question:'قوتان متعامدتان، الأولى شرقاً والثانية شمالاً. احسب مقدار المحصلة.',given:`Fx = ${3*k} N, Fy = ${4*k} N`,formula:'R = √(Fx² + Fy²)',substitution:`√(${3*k}² + ${4*k}²)`,answer:5*k,unit:'N',trap:'لا تجمع المقدارين مباشرة إلا عندما تكون القوتان في الاتجاه نفسه.'};},
  resolution: n => {const a=10+2*n;return {question:'متجه يصنع زاوية 60° مع المحور الأفقي الموجب. احسب مركبته الأفقية.',given:`A = ${a} N, θ = 60°`,formula:'Ax = A cos θ',substitution:`${a} × 0.5`,answer:a/2,unit:'N',trap:'الزاوية مقاسة من الأفقي؛ الأفقي هنا cos والرأسي sin.'};},
  displacement: n => {const x=2+n,y=-3-n;return {question:'انتقل جسم من الموقع الابتدائي إلى الموقع النهائي. احسب الإزاحة مع الإشارة.',given:`xi = ${x} m, xf = ${y} m`,formula:'Δx = xf − xi',substitution:`${y} − (${x})`,answer:y-x,unit:'m',trap:'اطرح الابتدائي من النهائي. الإشارة السالبة تعني اتجاه المحور السالب.'};},
  speed: n => {const t=4+n,v=3+n;return {question:'قطع جسم مسافة خلال زمن معلوم. احسب السرعة القياسية المتوسطة.',given:`S = ${t*v} m, t = ${t} s`,formula:'vs = S / t',substitution:`${t*v} ÷ ${t}`,answer:v,unit:'m/s',trap:'السرعة القياسية تعتمد على المسافة، لا الإزاحة.'};},
  convert: n => {const v=10+5*n;return {question:'حوّل السرعة التالية إلى متر في الثانية.',given:`v = ${v*3.6} km/h`,formula:'v(m/s) = v(km/h) ÷ 3.6',substitution:`${v*3.6} ÷ 3.6`,answer:v,unit:'m/s',trap:'من km/h إلى m/s نقسم على 3.6، والعكس نضرب.'};},
  accel: n => {const vi=4+n,t=2+n,a=2;return {question:'احسب تسارع جسم يتحرك في الاتجاه الموجب.',given:`vi = ${vi} m/s, vf = ${vi+t*a} m/s, Δt = ${t} s`,formula:'a = (vf − vi) / Δt',substitution:`(${vi+t*a} − ${vi}) ÷ ${t}`,answer:a,unit:'m/s²',trap:'التسارع هو تغير السرعة مقسوماً على الزمن، لا السرعة النهائية وحدها.'};},
  velocity: n => {const v=2+n,a=3,t=4+n;return {question:'احسب السرعة النهائية لجسم يتحرك بتسارع ثابت.',given:`vi = ${v} m/s, a = ${a} m/s², t = ${t} s`,formula:'vf = vi + at',substitution:`${v} + ${a} × ${t}`,answer:v+a*t,unit:'m/s',trap:'اضرب التسارع في الزمن أولاً ثم أضف السرعة الابتدائية.'};},
  freefall: n => {const t=1+n;return {question:'سقط جسم من السكون. احسب مقدار سرعة الجسم بعد الزمن المعطى، مع إهمال مقاومة الهواء وg = 10 m/s².',given:`vi = 0, t = ${t} s, g = 10 m/s²`,formula:'|v| = gt',substitution:`10 × ${t}`,answer:10*t,unit:'m/s',trap:'المطلوب مقدار السرعة؛ إذا كان الأعلى موجباً فإن مركبة السرعة نفسها سالبة.'};},
  projectile: n => {const v=10+5*n,t=2+n;return {question:'مقذوف مركبة سرعته الأفقية ثابتة. احسب الإزاحة الأفقية بعد الزمن المعطى، قبل ملامسة الأرض.',given:`vx = ${v} m/s, t = ${t} s`,formula:'Δx = vx t',substitution:`${v} × ${t}`,answer:v*t,unit:'m',trap:'عند إهمال مقاومة الهواء لا يوجد تسارع أفقي.'};},
  circular: n => {const v=4+2*n,r=2;return {question:'احسب مقدار التسارع المركزي في حركة دائرية منتظمة.',given:`v = ${v} m/s, r = ${r} m`,formula:'ac = v² / r',substitution:`${v}² ÷ ${r}`,answer:v*v/r,unit:'m/s²',trap:'ثبات مقدار السرعة لا يعني انعدام التسارع؛ اتجاه السرعة يتغير.'};},
  newton: n => {const m=2+n,a=3+n;return {question:'احسب القوة المحصلة المؤثرة في جسم معلوم الكتلة والتسارع.',given:`m = ${m} kg, a = ${a} m/s²`,formula:'ΣF = ma',substitution:`${m} × ${a}`,answer:m*a,unit:'N',trap:'القانون يربط التسارع بالقوة المحصلة، وليس بأي قوة منفردة.'};},
  gravity: n => {const f=40+8*n;return {question:'إذا تضاعفت المسافة بين مركزي جسمين وبقيت الكتلتان ثابتتين، فما قوة التجاذب الجديدة؟',given:`F1 = ${f} N, r2 = 2r1`,formula:'F2 = F1 / 2²',substitution:`${f} ÷ 4`,answer:f/4,unit:'N',trap:'قوة الجذب تتناسب عكسياً مع مربع المسافة، لا المسافة وحدها.'};}
};
function drillFor(h: InteractiveHotspot): DrillFactory | undefined {
  const p=h.page;
  if(p===7) return drills.weight;
  if(h.id==='p14-dot-product') return drills.scalar;
  if(h.id==='p14-cross-product') return drills.cross;
  if(p===15) return drills.work;
  if(p===23||p===24) return drills.resolution;
  if(p>=17&&p<=28) return drills.vector;
  if(p===36||p===37) return drills.displacement;
  if(p===38||p===40) return drills.speed;
  if(p===39) return drills.convert;
  if(p>=41&&p<=44) return drills.accel;
  if(p>=49&&p<=51) return drills.velocity;
  if(p>=52&&p<=55) return drills.freefall;
  if(p>=57&&p<=62) return drills.projectile;
  if(p>=63&&p<=65) return drills.circular;
  if(p>=70&&p<=74) return drills.newton;
  if(p===77) return drills.gravity;
  return undefined;
}
function NumericPractice({factory}: {factory: DrillFactory}) {
  const [round,setRound]=useState(0);
  const [input,setInput]=useState('');
  const [hint,setHint]=useState(0);
  const [result,setResult]=useState<'correct'|'wrong'|null>(null);
  const [reveal,setReveal]=useState(false);
  const q=factory(round%9);
  const value=Number(input.trim().replace(/[٠-٩]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(c))).replace(/[۰-۹]/g,c=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(c))).replace(/[٫,]/g,'.').replace(/−/g,'-'));
  const valid=input.trim()!==''&&Number.isFinite(value);
  const check=()=>{if(valid)setResult(Math.abs(value-q.answer)<=Math.max(.01,Math.abs(q.answer)*.001)?'correct':'wrong');};
  const next=()=>{setRound(n=>n+1);setInput('');setHint(0);setResult(null);setReveal(false);};
  return <section id="learn-practice" className="bg-white border border-teal-200 rounded-2xl p-4 space-y-3">
    <div className="flex items-center gap-2"><Target className="w-5 h-5 text-teal-700"/><h4 className="text-sm font-black">دورك تحل — مثال بأرقام جديدة</h4></div>
    <p className="text-sm leading-relaxed font-semibold">{q.question}</p><div dir="ltr" className="bg-slate-100 rounded-xl p-3 text-center font-mono text-sm">{q.given}</div>
    <form onSubmit={e=>{e.preventDefault();check();}} className="flex gap-2 items-center"><input aria-label="إجابتك الرقمية" type="text" inputMode="decimal" dir="ltr" value={input} onChange={e=>{setInput(e.target.value);setResult(null);}} placeholder="?" className="min-w-0 flex-1 border border-slate-300 rounded-lg px-3 py-2 text-center"/><span dir="ltr" className="text-xs font-bold text-slate-500">{q.unit}</span><button disabled={!valid} type="submit" className="bg-teal-700 text-white font-bold rounded-lg px-3 py-2 text-sm disabled:opacity-40">تحقق</button></form>
    {result&&<p role="status" className={`p-3 rounded-lg text-sm ${result==='correct'?'bg-emerald-50 text-emerald-900':'bg-amber-50 text-amber-900'}`}>{result==='correct'?'ممتاز، إجابتك صحيحة! جرّب مثالاً آخر لتثبيت الفكرة.':q.trap+' جرّب مرة ثانية أو اطلب تلميحاً.'}</p>}
    {hint>0&&<div className="bg-sky-50 text-sky-950 rounded-lg p-3 text-xs space-y-2"><p className="font-bold">التلميح 1: القانون المناسب</p><p dir="ltr" className="font-mono text-center">{q.formula}</p>{hint>1&&<><p className="font-bold">التلميح 2: التعويض</p><p dir="ltr" className="font-mono text-center">{q.substitution}</p></>}</div>}
    {reveal&&<div className="bg-emerald-50 text-emerald-950 rounded-lg p-3 text-sm space-y-2"><p>الحل الكامل:</p><p dir="ltr" className="font-mono text-center">{q.formula}</p><p dir="ltr" className="font-mono text-center">{q.substitution} = {q.answer} {q.unit}</p><p className="text-xs">{q.trap}</p></div>}
    <div className="flex flex-wrap gap-2"><button type="button" disabled={hint>=2} onClick={()=>setHint(h=>Math.min(2,h+1))} className="rounded-lg border border-sky-200 text-sky-800 p-2 text-xs font-bold disabled:opacity-40"><Lightbulb className="w-4 h-4 inline"/> تلميح ({hint}/2)</button><button type="button" onClick={()=>setReveal(v=>!v)} className="rounded-lg border border-slate-200 p-2 text-xs font-bold">{reveal?'أخفِ الحل':'أرني الحل'}</button><button type="button" onClick={next} className="rounded-lg border border-teal-200 text-teal-800 p-2 text-xs font-bold"><RotateCcw className="w-4 h-4 inline"/> أرقام جديدة</button></div>
  </section>;
}
interface HotspotExplanationDrawerProps {
  hotspot: InteractiveHotspot | null;
  pageHotspots: InteractiveHotspot[];
  teacherHideAnswers: boolean;
  teacherPauseSim: boolean;
  onClose: () => void;
  onSelectHotspot: (hotspot: InteractiveHotspot) => void;
}

export default function HotspotExplanationDrawer({
  hotspot,
  pageHotspots,
  teacherHideAnswers,
  teacherPauseSim,
  onClose,
  onSelectHotspot,
}: HotspotExplanationDrawerProps) {
  const [revealedStepsCount, setRevealedStepsCount] = useState(0);
  const [showSubstitution, setShowSubstitution] = useState(false);
  const [quizAnswers, setQuizAnswers] = useState<Record<number, number>>({});
  const [guided, setGuided] = useState(true);
  const [showTip, setShowTip] = useState(false);

  useEffect(() => {
    if (!hotspot) return;
    // If Teacher Mode hides answers, start with 0 steps revealed so teacher controls pace; otherwise show step 1 or all.
    setRevealedStepsCount(teacherHideAnswers || guided ? 0 : hotspot.steps?.length ?? 0);
    setShowSubstitution(!teacherHideAnswers && !guided);
    setShowTip(false);
  }, [hotspot, teacherHideAnswers, guided]);
  useEffect(()=>{setQuizAnswers({});},[hotspot]);

  if (!hotspot) return null;

  const currentIdx = pageHotspots.findIndex((h) => h.id === hotspot.id);
  const hasPrev = currentIdx > 0;
  const hasNext = currentIdx >= 0 && currentIdx < pageHotspots.length - 1;
  const totalSteps = hotspot.steps?.length ?? 0;
  const factory=drillFor(hotspot);
  const goTo=(id:string)=>document.getElementById(id)?.scrollIntoView({block:'start',behavior:'auto'});

  return (
    <aside
      aria-label="لوحة الشرح والمحاكاة التفاعلية"
      data-testid="hotspot-drawer"
      className="fixed inset-x-0 bottom-0 top-14 z-40 lg:static lg:z-10 w-full lg:w-[460px] xl:w-[500px] lg:max-h-[calc(100vh-110px)] lg:sticky lg:top-[106px] bg-slate-50 border-t lg:border-t-0 lg:border-r border-slate-200 shadow-2xl lg:shadow-none flex flex-col shrink-0"
    >
      {/* Header */}
      <div className="bg-white border-b border-slate-200 px-5 py-4 flex items-start justify-between gap-3 shrink-0">
        <div className="space-y-1">
          <div className="flex items-center gap-2 text-xs font-bold text-sky-700">
            <BookOpen className="w-3.5 h-3.5" />
            <span>صفحة {hotspot.page} من الكتاب المدرسي</span>
          </div>
          <h3 className="text-base font-extrabold text-slate-900 leading-snug">{hotspot.title}</h3>
        </div>

        <button
          type="button"
          onClick={onClose}
          aria-label="إغلاق لوحة الشرح"
          className="p-2 rounded-lg text-slate-500 hover:text-slate-900 hover:bg-slate-100 transition-colors shrink-0"
        >
          <X className="w-5 h-5" />
        </button>
      </div>

      {/* Prev / Next Hotspot in Current Page */}
      {pageHotspots.length > 1 && (
        <div className="bg-white border-b border-slate-200 px-5 py-2 flex items-center justify-between text-xs shrink-0">
          <button
            type="button"
            disabled={!hasPrev}
            onClick={() => hasPrev && onSelectHotspot(pageHotspots[currentIdx - 1])}
            className="inline-flex items-center gap-1 px-2.5 py-1 rounded-md font-semibold text-slate-700 hover:bg-slate-100 disabled:opacity-40 whitespace-nowrap"
          >
            <ChevronRight className="w-4 h-4" />
            السابق بالصفحة
          </button>
          <span className="text-slate-500 tabular-nums font-medium">
            {currentIdx + 1} من {pageHotspots.length}
          </span>
          <button
            type="button"
            disabled={!hasNext}
            onClick={() => hasNext && onSelectHotspot(pageHotspots[currentIdx + 1])}
            className="inline-flex items-center gap-1 px-2.5 py-1 rounded-md font-semibold text-slate-700 hover:bg-slate-100 disabled:opacity-40 whitespace-nowrap"
          >
            التالي بالصفحة
            <ChevronLeft className="w-4 h-4" />
          </button>
        </div>
      )}

      <div className="shrink-0 bg-[#112b49] text-white px-4 py-3 space-y-2">
        <div className="flex items-center justify-between gap-2"><span className="text-xs font-bold inline-flex gap-1.5 items-center"><Brain className="w-4 h-4 text-teal-200"/> طريقة التعلّم</span><button type="button" onClick={()=>setGuided(g=>!g)} aria-pressed={guided} className="text-xs font-bold px-3 py-1.5 rounded-lg bg-white/10 hover:bg-white/20">{guided?'متدرج · التبديل للشرح الكامل':'كامل · التبديل للشرح المتدرج'}</button></div>
        <div className="flex flex-wrap gap-1.5 text-xs">
          <button type="button" onClick={()=>goTo('learn-concept')} className="bg-white/10 rounded-lg px-2 py-1.5">١. افهم</button>
          {hotspot.formula&&<button type="button" onClick={()=>goTo('learn-formula')} className="bg-white/10 rounded-lg px-2 py-1.5">٢. القانون</button>}
          {totalSteps>0&&<button type="button" onClick={()=>goTo('learn-steps')} className="bg-white/10 rounded-lg px-2 py-1.5">٣. حل خطوة خطوة</button>}
          {hotspot.simulation&&<button type="button" onClick={()=>goTo('learn-lab')} className="bg-white/10 rounded-lg px-2 py-1.5">جرّب</button>}
          {factory&&!teacherHideAnswers&&<button type="button" onClick={()=>goTo('learn-practice')} className="bg-teal-300 text-slate-900 font-bold rounded-lg px-2 py-1.5">دورك تحل</button>}
          {!!hotspot.quiz?.length&&<button type="button" onClick={()=>goTo('learn-quiz')} className="bg-white/10 rounded-lg px-2 py-1.5">اختبر فهمك</button>}
        </div>
      </div>
      {/* Scrollable Body */}
      <div className="flex-1 overflow-y-auto p-5 space-y-5">
        {/* 1. Simplified Explanation + Teaching Tip */}
        <section id="learn-concept" className="bg-white border border-slate-200 rounded-2xl p-4 space-y-3">
          <h4 className="text-base font-black text-slate-900">الفكرة ببساطة</h4>
          <p className="text-[15px] text-slate-700 leading-loose">{teacherHideAnswers && (hotspot.category==='example'||hotspot.category==='question'||hotspot.category==='review') ? 'حاول أولاً تحديد المعطيات والمطلوب واختيار القانون المناسب، ثم اكشف خطوات الحل عند الحاجة.' : hotspot.simpleExplanation}</p>

          <div className="bg-amber-50 border border-amber-200 rounded-lg p-3 flex items-start gap-2.5">
            <Lightbulb className="w-4 h-4 text-amber-600 shrink-0 mt-0.5" />
            <div className="text-xs text-amber-950 leading-relaxed">
              <button type="button" onClick={()=>setShowTip(t=>!t)} className="font-bold block mb-0.5 text-right" aria-expanded={showTip}>{showTip?'إخفاء طريقة التذكر':'طريقة أسهل لتذكر الفكرة +'}</button>
              {showTip && (teacherHideAnswers ? 'اربط المطلوب بالكميات المعطاة، وراجع وحدات القياس قبل التعويض.' : hotspot.teachingTip)}
            </div>
          </div>
        </section>

        {/* 2. Formula Breakdown */}
        {hotspot.formula && (
          <section id="learn-formula" className="bg-white border border-slate-200 rounded-xl p-4 space-y-3">
            <div className="flex items-center justify-between gap-2">
              <div className="flex items-center gap-2">
                <Calculator className="w-4 h-4 text-indigo-600" />
                <h4 className="text-sm font-bold text-slate-900">{hotspot.formula.title}</h4>
              </div>
              <button
                type="button"
                onClick={() => setShowSubstitution((s) => !s)}
                className="inline-flex items-center gap-1 text-xs font-semibold text-indigo-700 hover:text-indigo-900"
              >
                {showSubstitution ? <EyeOff className="w-3.5 h-3.5" /> : <Eye className="w-3.5 h-3.5" />}
                {showSubstitution ? 'إخفاء التعويض' : 'عرض التعويض'}
              </button>
            </div>

            <div
              dir="ltr"
              className="bg-slate-900 text-sky-300 rounded-lg px-4 py-3 text-center font-mono text-sm font-bold tracking-wide"
            >
              {hotspot.formula.equation}
            </div>

            <div className="grid grid-cols-1 gap-2">
              {hotspot.formula.symbols.map((sym) => (
                <div
                  key={sym.symbol}
                  className="flex items-center justify-between gap-2 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-xs"
                >
                  <div className="flex items-center gap-2">
                    <span
                      dir="ltr"
                      className="px-2 py-0.5 rounded bg-indigo-100 text-indigo-800 font-mono font-bold"
                    >
                      {sym.symbol}
                    </span>
                    <span className="text-slate-700 font-medium">{sym.name}</span>
                  </div>
                  <span className="text-slate-500 font-semibold tabular-nums shrink-0">{sym.unit}</span>
                </div>
              ))}
            </div>

            {showSubstitution && hotspot.formula.sampleSubstitution.length > 0 && (
              <div className="bg-indigo-50 border border-indigo-200 rounded-lg p-3 space-y-1 text-xs text-indigo-950">
                <span className="font-bold block">التعويض الخطوة بالخطوة:</span>
                {hotspot.formula.sampleSubstitution.map((line, i) => (
                  <p key={i} className="leading-relaxed tabular-nums">
                    • {line}
                  </p>
                ))}
              </div>
            )}
          </section>
        )}

        {/* 3. Progressive Step-by-Step Solution */}
        {hotspot.steps && totalSteps > 0 && (
          <section id="learn-steps" className="bg-white border border-slate-200 rounded-xl p-4 space-y-3">
            <div className="flex flex-wrap items-center justify-between gap-2">
              <div className="flex items-center gap-2">
                <ListChecks className="w-4 h-4 text-emerald-600" />
                <h4 className="text-sm font-bold text-slate-900">خطوات الحل التدريجي</h4>
              </div>

              <div className="flex items-center gap-2">
                {revealedStepsCount < totalSteps && (
                  <button
                    type="button"
                    onClick={() => setRevealedStepsCount((c) => Math.min(totalSteps, c + 1))}
                    className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold transition-colors whitespace-nowrap"
                  >
                    <Eye className="w-3.5 h-3.5" />
                    اكشف الخطوة التالية ({revealedStepsCount}/{totalSteps})
                  </button>
                )}
                {revealedStepsCount > 0 && (
                  <button
                    type="button"
                    onClick={() => setRevealedStepsCount(0)}
                    className="inline-flex items-center gap-1 px-2 py-1 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-semibold transition-colors whitespace-nowrap"
                  >
                    <EyeOff className="w-3.5 h-3.5" />
                    إخفاء
                  </button>
                )}
              </div>
            </div>

            {revealedStepsCount === 0 ? (
              <div className="bg-slate-50 border border-dashed border-slate-300 rounded-lg p-4 text-center text-xs text-slate-600">
                قبل الحل: ما المعطيات؟ ما المطلوب؟ أي قانون يربطهما؟ حاول بنفسك ثم اكشف الخطوة التالية.
              </div>
            ) : (
              <div className="space-y-2">
                {hotspot.steps.slice(0, revealedStepsCount).map((step, idx) => (
                  <div
                    key={idx}
                    className="bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-xs text-slate-800 leading-relaxed"
                  >
                    <span className="inline-grid place-items-center w-6 h-6 rounded-full bg-teal-100 text-teal-900 font-bold ml-2">{idx+1}</span>{step}
                  </div>
                ))}

                {revealedStepsCount === totalSteps && hotspot.finalAnswer && (
                  <div className="bg-emerald-50 border border-emerald-200 rounded-lg px-3 py-2.5 text-xs font-bold text-emerald-900">
                    النتيجة النهائية: {hotspot.finalAnswer}
                  </div>
                )}
              </div>
            )}
          </section>
        )}

        {/* 4. Embedded Live Physics Simulation */}
        {hotspot.simulation && (
          <section id="learn-lab" className="space-y-2">
            <div className="flex items-center gap-2 text-xs font-bold text-slate-700 px-1">
              <PlayCircle className="w-4 h-4 text-sky-600" />
              <span>جرّب المحاكاة الفيزيائية المباشرة لهذا المفهوم:</span>
            </div>
            <SimulationLab simulationId={hotspot.simulation} isPaused={teacherPauseSim} />
          </section>
        )}

        {factory && !teacherHideAnswers && <NumericPractice key={hotspot.id} factory={factory}/>}
        {/* 5. Quick Quiz */}
        {hotspot.quiz && hotspot.quiz.length > 0 && (
          <section id="learn-quiz" className="bg-white border border-slate-200 rounded-xl p-4 space-y-4">
            <h4 className="text-sm font-bold text-slate-900">اختبار فهم سريع</h4>
            {hotspot.quiz.map((q, qIdx) => {
              const selected = quizAnswers[qIdx];
              const answered = selected !== undefined;
              const isCorrect = selected === q.correctIndex;

              return (
                <div key={qIdx} className="space-y-2.5 border-t border-slate-100 pt-3 first:border-t-0 first:pt-0">
                  <p className="text-xs font-bold text-slate-800 leading-relaxed">{q.question}</p>
                  <div className="space-y-1.5">
                    {q.options.map((opt, oIdx) => {
                      const isThisSelected = selected === oIdx;
                      const isThisCorrect = oIdx === q.correctIndex;
                      let btnStyle = 'bg-slate-50 border-slate-200 text-slate-800 hover:bg-slate-100';
                      if (answered) {
                        if (teacherHideAnswers) {
                          if (isThisSelected) btnStyle = 'bg-sky-50 border-sky-400 text-sky-900 font-bold';
                        } else if (isThisCorrect) {
                          btnStyle = 'bg-emerald-50 border-emerald-400 text-emerald-900 font-bold';
                        } else if (isThisSelected && !isThisCorrect) {
                          btnStyle = 'bg-rose-50 border-rose-400 text-rose-900';
                        }
                      }

                      return (
                        <button
                          key={oIdx}
                          type="button"
                          onClick={() => setQuizAnswers((prev) => ({ ...prev, [qIdx]: oIdx }))}
                          className={`w-full text-right px-3 py-2 rounded-lg border text-xs transition-colors flex items-center justify-between gap-2 ${btnStyle}`}
                        >
                          <span>{opt}</span>
                          {answered && !teacherHideAnswers && isThisCorrect && (
                            <CheckCircle2 className="w-4 h-4 text-emerald-600 shrink-0" />
                          )}
                          {answered && !teacherHideAnswers && isThisSelected && !isThisCorrect && (
                            <XCircle className="w-4 h-4 text-rose-600 shrink-0" />
                          )}
                        </button>
                      );
                    })}
                  </div>

                  {answered && !teacherHideAnswers && (
                    <div
                      className={`p-2.5 rounded-lg text-xs leading-relaxed ${
                        isCorrect ? 'bg-emerald-50 text-emerald-900' : 'bg-amber-50 text-amber-900'
                      }`}
                    >
                      {q.explanation}
                    </div>
                  )}
                  {answered && teacherHideAnswers && (
                    <div className="p-2 rounded-lg text-xs bg-slate-100 text-slate-700">
                      تم تسجيل اختيارك — أطفئ "إخفاء الحلول" من وضع المعلم لكشف النتيجة والتعليل.
                    </div>
                  )}
                </div>
              );
            })}
          </section>
        )}
      </div>
    </aside>
  );
}
